/*!
 * 轻量 HTML 白名单净化（生产环境建议替换为官方 DOMPurify）
 * 暴露 window.DOMPurify.sanitize(html, cfg) -> 安全 HTML 字符串
 * 默认允许常见排版标签，仅放行 http/https 链接，剥离事件与脚本。
 */
(function (global) {
  'use strict';

  var ALLOWED_TAGS = {
    p: 1, br: 1, strong: 1, em: 1, b: 1, i: 1, u: 1, s: 1, del: 1,
    code: 1, pre: 1, span: 1, div: 1, blockquote: 1, hr: 1,
    h1: 1, h2: 1, h3: 1, h4: 1, h5: 1, h6: 1,
    ul: 1, ol: 1, li: 1,
    table: 1, thead: 1, tbody: 1, tr: 1, th: 1, td: 1, caption: 1,
    a: 1, img: 1, sup: 1, sub: 1
  };
  var ALLOWED_ATTRS = {
    a: ['href', 'target', 'rel', 'class'],
    img: ['src', 'alt', 'style'],
    span: ['class'], div: ['class'],
    code: ['class'], pre: ['class'],
    td: ['colspan', 'rowspan'], th: ['colspan', 'rowspan'],
    table: ['class'], ul: ['class'], ol: ['class', 'start'], li: ['class']
  };

  function cleanUrl(url) {
    var u = String(url || '').trim();
    return /^(https?:|mailto:)/i.test(u) ? u : '';
  }

  function walk(node, stripLinks) {
    var out = '';
    node.childNodes.forEach(function (child) {
      if (child.nodeType === 3) {
        out += child.textContent
          .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        return;
      }
      if (child.nodeType !== 1) return;
      var tag = child.tagName.toLowerCase();
      if (!ALLOWED_TAGS[tag]) { out += walk(child, stripLinks); return; }
      if (tag === 'a' && stripLinks) { out += walk(child, stripLinks); return; }
      var attrs = '';
      var allowed = ALLOWED_ATTRS[tag] || [];
      for (var k = 0; k < child.attributes.length; k++) {
        var a = child.attributes[k];
        var name = a.name.toLowerCase();
        if (allowed.indexOf(name) < 0) continue;
        var value = a.value;
        if (name === 'href' || name === 'src') {
          if (tag === 'img' && name === 'src' && /^data:image\//.test(value)) {
            // 放行 data 图片
          } else {
            value = cleanUrl(value);
            if (!value) continue;
          }
        }
        value = value.replace(/"/g, '&quot;');
        attrs += ' ' + name + '="' + value + '"';
      }
      if (tag === 'a' && attrs.indexOf('href') < 0) { out += walk(child, stripLinks); return; }
      if (tag === 'a') attrs += ' target="_blank" rel="noopener noreferrer"';
      if (tag === 'br' || tag === 'hr' || tag === 'img') {
        out += '<' + tag + attrs + '>';
        return;
      }
      out += '<' + tag + attrs + '>' + walk(child, stripLinks) + '</' + tag + '>';
    });
    return out;
  }

  function sanitize(html, cfg) {
    var tpl = document.createElement('template');
    tpl.innerHTML = String(html == null ? '' : html);
    return walk(tpl.content, !!(cfg && cfg.stripLinks));
  }

  global.DOMPurify = { sanitize: sanitize };
})(window);
